function evalPrefix(tokens) {
  const stack = [];
  for (let i = tokens.length - 1; i >= 0; i--) {   // right to left
    const t = tokens[i];
    if (t === "+" || t === "-" || t === "*" || t === "/") {
      const a = stack.pop();       // reading backwards, the left operand is on top
      const b = stack.pop();
      if (t === "+") stack.push(a + b);
      else if (t === "-") stack.push(a - b);
      else if (t === "*") stack.push(a * b);
      else stack.push(Math.trunc(a / b));
    } else {
      stack.push(Number(t));
    }
  }
  return stack.pop();
}

